import type { AgentRuntimeContractId } from "../../../shared/agent-runtime-capabilities"
import { getAgentRuntimeCapabilityManifest } from "../../../shared/agent-runtime-capabilities"
import { runClaudeAgentSdkDesktopAdapterWithPreparedRuntimeQuery } from "../claude/agent-sdk-adapter-runner"
import { runCodexAppServerDesktopAdapter } from "../codex/app-server-adapter-runner"
import { runClaudeCodeHeadlessTask } from "../headless/adapters/claude-code"
import { createCodexAppServerHeadlessTaskRunner } from "../headless/adapters/codex-app-server"
import { runCodexHeadlessTask } from "../headless/adapters/codex"

const RUNTIME_ROUTE_DECLARATIONS = [
  { routeId: "claude-code.desktop", runtimeId: "claude-code", entry: "desktop", adapterSource: "claude-agent-sdk", delegate: () => runClaudeAgentSdkDesktopAdapterWithPreparedRuntimeQuery },
  { routeId: "codex.desktop", runtimeId: "codex", entry: "desktop", adapterSource: "codex-app-server", delegate: () => runCodexAppServerDesktopAdapter },
  { routeId: "claude-code.headless.batch", runtimeId: "claude-code", entry: "headless", adapterSource: "claude-code-batch", delegate: () => runClaudeCodeHeadlessTask },
  { routeId: "codex.headless.batch", runtimeId: "codex", entry: "headless", adapterSource: "codex-batch", delegate: () => runCodexHeadlessTask },
  { routeId: "codex.api.policy-grant", runtimeId: "codex", entry: "api", adapterSource: "codex-app-server", delegate: () => createCodexAppServerHeadlessTaskRunner() },
] as const

export function resolveRuntimeRoute(query: { runtimeId: AgentRuntimeContractId; entry: string }) {
  const manifest = getAgentRuntimeCapabilityManifest(query.runtimeId)
  const route = RUNTIME_ROUTE_DECLARATIONS.find(
    (candidate) => candidate.runtimeId === query.runtimeId && candidate.entry === query.entry,
  )
  return route && manifest ? { ok: true as const, ...route } : { ok: false as const, reason: "route_not_found" as const }
}

import type { AgentRuntimeObserver, AgentRuntimeRunRequest } from "./agent-runtime-contract"
import { runClaudeCodeHeadlessTask } from "./adapters/claude-code"
import { runCodexHeadlessTask } from "./adapters/codex"

export async function runAgentTask(request: AgentRuntimeRunRequest, observer: AgentRuntimeObserver) {
  if (request.context.runtimeId === "codex") {
    return runCodexHeadlessTask(request, observer)
  }
  return runClaudeCodeHeadlessTask(request, observer)
}

import { CodexAppServerChatTransport } from "./codex-app-server-chat-transport"
