type TransportConfig = ConstructorParameters<typeof IPCChatTransport>[0]

export function selectChatTransport(binding: { runtime: string }, config: TransportConfig) {
  switch (binding.runtime) {
    case "codex":
      return new CodexAppServerChatTransport({ ...config, provider: "codex" })
    default:
      return new IPCChatTransport(config)
  }
}

