export type DesktopRuntimeAdapterMetadata = { runtimeId: string; adapterSource: string }

export function assertDesktopRuntimeAdapterMatchesRequest(metadata: DesktopRuntimeAdapterMetadata, request: DesktopRunRequest) {
  if (metadata.runtimeId !== request.runtimeId) {
    throw new Error("Desktop runtime adapter does not match the request.")
  }
}

export async function recordDesktopRuntimeAdapterStarted(request: DesktopRunRequest, metadata: DesktopRuntimeAdapterMetadata) {
  await request.ledger?.appendSystemEvent("adapter_started", metadata)
}

export function assertAppServerPolicyGrantRequest(request: {
  context: { runtimeId: string; executionProfile?: string }
  permissionPolicy: { kind: string; grantedScopes?: readonly string[] }
}) {
  if (request.context.runtimeId !== "codex") {
    throw new Error("Codex app-server headless adapter requires the codex runtime.")
  }
  if (request.context.executionProfile !== "policy-grant") {
    throw new Error("Codex app-server headless adapter requires the policy-grant execution profile.")
  }
  if (!request.permissionPolicy.grantedScopes?.length) {
    throw new Error("Codex app-server headless adapter requires bounded granted scopes.")
  }
}

