type TransportConfig = ConstructorParameters<typeof IPCChatTransport>[0]

export function useChatTransports(newSubChat: { binding: { runtime: string } }, config: TransportConfig) {
  const getOrCreateChat = (binding: { runtime: string }) => {
    const chatProvider = binding.runtime
    let transport: IPCChatTransport | CodexAppServerChatTransport | null = null
    if (chatProvider === "codex") {
      transport = new CodexAppServerChatTransport({ ...config, provider: "codex" })
    } else {
      transport = new IPCChatTransport(config)
    }
    return transport
  }
  return { getOrCreateChat }
}

