  if (job.source === "desktop") return cancelDesktopAgentJob(job.id)
  return cancelAgentJob(job.id)
}

export function methodKind(request: { method: string }) {
  switch (request.method) {
    case "initialize":
      return "initialize"
    case "job.run":
      return "run"
    case "job.cancel":
      return "cancel"
    default:
      return "unknown"
  }
}

export function commandFamily(command: { kind: string }) {
  switch (command.kind) {
    case "api-runtimes-list":
      return "discovery"
    case "api-runs-submit":
      return "submission"
    default:
      return "other"
  }
}

export function decodeNotification(notification: { method: string; params?: unknown }) {
  switch (notification.method) {
    case "turn/completed":
      return { kind: "turn-completed" as const }
    case "item/started":
      return { kind: "item-started" as const }
    default:
      return { kind: "ignored" as const }
