import { resolveRuntimeRoute, type RuntimeRouteCatalogState } from "../agent-runtime/runtime-route-catalog"

export type CodexDesktopChatRunOptions = { request: unknown; runtimeRouteCatalog?: RuntimeRouteCatalogState }

export async function runCodexDesktopChatRun(options: CodexDesktopChatRunOptions) {
  const route = resolveRuntimeRoute({ runtimeId: "codex", entry: "desktop" }, options.runtimeRouteCatalog)
  if (!route.ok || route.runtimeId !== "codex" || route.executionSurface !== "desktop-app-server") {
    throw new Error("Runtime route catalog is unavailable.")
  }
  return route.delegate(options.request)
}

import { CodexAppServerChatTransport } from "./codex-app-server-chat-transport"
import { IPCChatTransport } from "./ipc-chat-transport"

const TRANSPORT_CONSTRUCTORS = {
  "claude-chat-ipc": IPCChatTransport,
  "codex-chat-ipc": CodexAppServerChatTransport,
} as const

export function createRuntimeRouteTransport(
  input: { state: "loaded"; transportId: string } | { state: "not-loaded" } | { state: "error" },
  config: never,
) {
  if (input.state === "not-loaded") return { ok: false, failure: "route_descriptor_unavailable" } as const
  if (input.state === "error") return { ok: false, failure: "route_descriptor_error" } as const
  const Transport = TRANSPORT_CONSTRUCTORS[input.transportId as keyof typeof TRANSPORT_CONSTRUCTORS]
  if (!Transport) return { ok: false, failure: "unknown_transport" } as const
  return { ok: true, transport: new Transport(config) } as const
}

export function reduceRuntimeChunk(state: { questions: number; guards: number }, chunk: { type: string }) {
  switch (chunk.type) {
    case "question":
      return { ...state, questions: state.questions + 1 }
    case "guard":
      return { ...state, guards: state.guards + 1 }
    default:
      return state
  }
}

function rejectStaleRunPayload(binding: { runtime: string }) {
  return { ok: false as const, runtime: binding.runtime }
}

export function providerTargetForBinding(binding: { runtime: string }) {
  return binding.runtime === "codex" ? "codex" : "claude"
}

export function admitClaudeChatSessionBindingRun(binding: { runtime: string }) {
  if (binding.runtime !== "claude-code") return rejectStaleRunPayload(binding)
  return { ok: true as const, binding }
}

export function admitCodexChatSessionBindingRun(binding: { runtime: string }) {
  if (binding.runtime !== "codex") return rejectStaleRunPayload(binding)
  return { ok: true as const, binding }
}

export function assertDesktopRuntime(runtime: string): asserts runtime is "claude-code" | "codex" {
  if (runtime !== "claude-code" && runtime !== "codex") {
    throw new Error(`Unsupported desktop runtime: ${runtime}`)
  }
}

import { trpcClient } from "../../../lib/trpc"

export function newChatSessionBindingDefaults(runtime: string, selection: { codexModelId?: string }) {
  if (runtime === "codex") {
    return { runtime, modelId: selection.codexModelId ?? "codex-default" }
