export function totalInputTokens(provider: string, metadata: { inputTokens?: number; totalTokens?: number; outputTokens?: number; cacheReadInputTokens?: number }) {
  return provider === "codex"
    ? Math.max(0, (metadata.totalTokens ?? 0) - (metadata.outputTokens ?? 0))
    : (metadata.inputTokens ?? 0) + (metadata.cacheReadInputTokens ?? 0)
}

