export async function runClaudeAgentSdkDesktopRuntimeWithMcpReadiness(input: {
  query: never
  runtimeRouteCatalog?: RuntimeRouteCatalogState
}) {
  const route = resolveRuntimeRoute({ runtimeId: "claude-code", entry: "desktop" }, input.runtimeRouteCatalog)
  if (!route.ok || route.runtimeId !== "claude-code") {
    throw new Error("Runtime route catalog is unavailable.")
  }
  return runClaudeAgentSdkRuntimeLifecycle({ runDelegate: route.delegate, query: input.query })
}

import { projectRuntimeRoutes, type RuntimeRouteCatalogState } from "./runtime-route-catalog"

export function withRuntimeRouteTransportId<T extends { runtime: string }>(binding: T, catalog?: RuntimeRouteCatalogState) {
  const projection = projectRuntimeRoutes("renderer", catalog)
  if (!projection.ok) return { ...binding }
  const route = projection.routes.find((entry) => entry.runtimeId === binding.runtime)
  return route ? { ...binding, transportId: route.transportId } : { ...binding }
}

