import { resolveRuntimeRoute, type RuntimeRouteCatalogState } from "../agent-runtime/runtime-route-catalog"
import type { AgentRuntimeObserver, AgentRuntimeRunRequest } from "./agent-runtime-contract"

declare function toRouteQuery(request: AgentRuntimeRunRequest): never

export async function runAgentTask(
  request: AgentRuntimeRunRequest,
  observer: AgentRuntimeObserver,
  options: { runtimeRouteCatalog?: RuntimeRouteCatalogState } = {},
) {
  const route = resolveRuntimeRoute(toRouteQuery(request), options.runtimeRouteCatalog)
  if (!route.ok) throw new Error("Runtime route catalog is unavailable.")
  return route.delegate(request, observer)
}

import type { AgentRuntimeObserver, AgentRuntimeRunRequest } from "./agent-runtime-contract"
import { selectAgentRuntimeAdapter } from "./adapter-selector"

export async function runAgentTask(request: AgentRuntimeRunRequest, observer: AgentRuntimeObserver) {
  const selection = selectAgentRuntimeAdapter(request)
  return selection.ok ? selection.adapter.run(request, observer) : selection.result
}

import { resolveRuntimeRoute } from "../agent-runtime/runtime-route-catalog"
import { legacyRouteCatalogState } from "./legacy-route-catalog-state"

export function routeFor(query: never) {
  const catalog = process.env.LOCUS_RUNTIME_ROUTE_PATH === "legacy" ? legacyRouteCatalogState : undefined
  return resolveRuntimeRoute(query, catalog)
}
